package com.collabspace.exception; import jakarta.servlet.http.HttpServletRequest;import jakarta.validation.ConstraintViolationException;import org.springframework.http.*;import org.springframework.security.authentication.BadCredentialsException;import org.springframework.web.bind.MethodArgumentNotValidException;import org.springframework.web.bind.annotation.*;import java.time.LocalDateTime;import java.util.NoSuchElementException;import java.util.stream.Collectors; @RestControllerAdvice public class GlobalExceptionHandler { @ExceptionHandler({ResourceNotFoundException.class,NoSuchElementException.class}) ResponseEntity<ApiError> notFound(Exception e,HttpServletRequest r){return err(HttpStatus.NOT_FOUND,e.getMessage(),r);} @ExceptionHandler({SecurityException.class}) ResponseEntity<ApiError> forbidden(Exception e,HttpServletRequest r){return err(HttpStatus.FORBIDDEN,e.getMessage(),r);} @ExceptionHandler(BadCredentialsException.class) ResponseEntity<ApiError> badCred(Exception e,HttpServletRequest r){return err(HttpStatus.UNAUTHORIZED,"Invalid email or password",r);} @ExceptionHandler(MethodArgumentNotValidException.class) ResponseEntity<ApiError> validation(MethodArgumentNotValidException e,HttpServletRequest r){String m=e.getBindingResult().getFieldErrors().stream().map(x->x.getField()+": "+x.getDefaultMessage()).collect(Collectors.joining(", "));return err(HttpStatus.BAD_REQUEST,m,r);} @ExceptionHandler({IllegalArgumentException.class,ConstraintViolationException.class}) ResponseEntity<ApiError> bad(Exception e,HttpServletRequest r){return err(HttpStatus.BAD_REQUEST,e.getMessage(),r);} @ExceptionHandler(Exception.class) ResponseEntity<ApiError> generic(Exception e,HttpServletRequest r){return err(HttpStatus.INTERNAL_SERVER_ERROR,"An unexpected error occurred.",r);} private ResponseEntity<ApiError> err(HttpStatus s,String m,HttpServletRequest r){return ResponseEntity.status(s).body(ApiError.builder().timestamp(LocalDateTime.now()).status(s.value()).error(s.name()).message(m).path(r.getRequestURI()).build());} }